mapper.select:
/***selectUdtWebUserList***/ SELECT CAST(COUNT(A.USER_ID) OVER() AS INTEGER) AS totcnt ,ROW_NUMBER() OVER (ORDER BY A.REG_DT ASC) AS rownum ,A.USER_ID ,A.USER_NAME ,A.USER_ROLE ,A.USER_ENABLED ,A.USER_EMAIL ,A.USER_PHONE_NUMBER ,TO_CHAR(TO_TIMESTAMP(A.REG_DT,'YYYYMMDDHH24MISS'),'YYYY.MM.DD') AS REG_DT ,TO_CHAR(TO_TIMESTAMP(A.UPDT_DT,'YYYYMMDDHH24MISS'),'YYYY.MM.DD') AS UPDT_DT FROM UDT_WEB_USER A WHERE 1=1
AND UPPER(A.USER_ID) LIKE '%' || UPPER(#{userId}) || '%'
AND A.USER_NAME LIKE '%' || #{userName} || '%'
AND A.USER_ROLE LIKE '%' || #{userRole} || '%'
ORDER BY A.REG_DT ASC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/***doUserIdCheck***/
SELECT 
COUNT(1) 
FROM UDT_WEB_USER 
WHERE USER_ID=#{userId};

mapper.insert:
INSERT INTO UDT_WEB_USER(
	USER_ID, USER_PASSWORD, USER_NAME, USER_AUTHORITY, USER_ROLE, USER_ENABLED, 
	USER_EMAIL, USER_PHONE_NUMBER,  REG_ID,  UPDT_ID)
VALUES (
		#{userId}
		,#{userPassword}
		,#{userName} 
		,#{userAuthority} 
		,#{userRole}
		,#{userEnabled} 
		,#{userEmail}
		,#{userPhoneNumber}
		,'ADMIN'
		,'ADMIN'
		);
